const views=[...document.querySelectorAll('.view')];const nav=[...document.querySelectorAll('.bottom-nav [data-view]')];function show(id){views.forEach(v=>v.classList.toggle('active',v.id===id));nav.forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'})}nav.forEach(b=>b.addEventListener('click',()=>show(b.dataset.view)));const sheet=document.querySelector('#sheet'),shade=document.querySelector('#shade'),title=document.querySelector('#sheetRoom');function openSheet(room){title.textContent=room;sheet.classList.add('open');shade.classList.add('on')}function closeSheet(){sheet.classList.remove('open');shade.classList.remove('on')}document.querySelectorAll('.room-card .book').forEach(btn=>btn.addEventListener('click',()=>openSheet(btn.closest('.room-card').dataset.room)));document.querySelector('#closeSheet').addEventListener('click',closeSheet);shade.addEventListener('click',closeSheet);document.querySelectorAll('.time-pills button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.time-pills button').forEach(x=>x.classList.remove('active'));btn.classList.add('active')}));document.querySelectorAll('.range button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.range button').forEach(x=>x.classList.remove('active'));btn.classList.add('active')}));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSheet()});